const { chromium } = require('/Users/josemejia/Documents/Software Development/Qualitara/relay-activity-health/.claude/worktrees/agent-af1bc63b76d53c82b/web/node_modules/playwright');
const fs = require('fs');
const path = require('path');
const beforeDir = path.join(__dirname, 'before');
const afterDir = path.join(__dirname, 'after');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  for (const name of fs.readdirSync(beforeDir).filter((file) => file.endsWith('.png'))) {
    const toDataUrl = (dir) => 'data:image/png;base64,' + fs.readFileSync(path.join(dir, name)).toString('base64');
    const result = await page.evaluate(async ([beforeUrl, afterUrl]) => {
      const load = (url) => new Promise((resolve) => { const image = new Image(); image.onload = () => resolve(image); image.src = url; });
      const [before, after] = await Promise.all([load(beforeUrl), load(afterUrl)]);
      if (before.width !== after.width || before.height !== after.height) {
        return `size ${before.width}x${before.height} vs ${after.width}x${after.height}`;
      }
      const pixels = (image) => {
        const canvas = document.createElement('canvas');
        canvas.width = image.width; canvas.height = image.height;
        const context = canvas.getContext('2d');
        context.drawImage(image, 0, 0);
        return context.getImageData(0, 0, image.width, image.height).data;
      };
      const beforePixels = pixels(before);
      const afterPixels = pixels(after);
      let differing = 0;
      let firstY = -1;
      for (let index = 0; index < beforePixels.length; index += 4) {
        if (beforePixels[index] !== afterPixels[index] || beforePixels[index + 1] !== afterPixels[index + 1] || beforePixels[index + 2] !== afterPixels[index + 2] || beforePixels[index + 3] !== afterPixels[index + 3]) {
          differing++;
          if (firstY < 0) firstY = Math.floor(index / 4 / before.width);
        }
      }
      return differing === 0 ? `identical (${before.width}x${before.height})` : `${differing} differing pixels, first at y=${firstY}`;
    }, [toDataUrl(beforeDir), toDataUrl(afterDir)]);
    console.log(`${name}: ${result}`);
  }
  await browser.close();
})();

